    "The agent is designed around your existing data infrastructure and access requirements, so you set the boundaries. That is what lets an organisation add voice automation on top of its own stack instead of moving a whole workflow into a separate platform.": "يُصمَّم الوكيل حول بنية بياناتك القائمة ومتطلبات الوصول لديك، فأنت من يحدد الحدود. وهذا ما يتيح للمؤسسة إضافة أتمتة صوتية فوق منظومتها التقنية بدلاً من نقل سير عمل كامل إلى منصة منفصلة.",
    "The agent understands what the caller wants, asks the right questions, pulls information from connected systems and acts on it. It is a conversational front end to your infrastructure rather than an isolated chatbot.": "يفهم الوكيل ما يريده المتصل، ويطرح الأسئلة الصحيحة، ويسحب المعلومات من الأنظمة المتصلة ويتصرف بناءً عليها. إنه واجهة حوارية أمامية لبنيتك التقنية وليس روبوت محادثة معزولاً.",
    "The analytics": "التحليلات",
    "The answer is in a folder nobody can search": "الإجابة في مجلد لا يستطيع أحد البحث فيه",
    "The league": "الدوري",
    "The same architecture adapts to support, recruitment, appointment management and other workflows.": "تتكيّف البنية نفسها مع الدعم والتوظيف وإدارة المواعيد وغيرها من مسارات العمل.",
    "There is a 10:30 slot. Shall I hold it for you?": "هناك موعد في 10:30. هل أحتفظ به لك؟",
