    "Enterprise delivery": "تنفيذ بمعايير المؤسسات",
    "Scalable, secure delivery trusted across 23+ countries.": "تنفيذ آمن وقابل للتوسع وموثوق به في أكثر من 23 دولة.",
    "Every DevelMo product here runs in production today, not as a demo. Adopt it as it is, or have it tailored to your environment.": "كل منتج من منتجات DevelMo هنا يعمل في بيئة إنتاج فعلية اليوم، وليس عرضاً تجريبياً. اعتمده كما هو، أو اطلب تخصيصه ليلائم بيئتك.",
    "One partner across the full stack of AI, product and infrastructure, with flexible teams that scale up or down with you.": "شريك واحد يغطي منظومة الذكاء الاصطناعي والمنتجات والبنية التحتية بالكامل، مع فرق مرنة تتوسع وتتقلص معك.",
