    "What cameras does CrowdIQ work with?": "ما الكاميرات التي يعمل معها CrowdIQ؟",
    "Any camera that exposes an RTSP, ONVIF or HTTP stream, plus local cameras and webcams. You do not need to replace existing hardware.": "أي كاميرا توفّر بث RTSP أو ONVIF أو HTTP، إضافة إلى الكاميرات المحلية وكاميرات الويب. لا حاجة لاستبدال أجهزتك الحالية.",
