    "Our custom-trained models reach 90-95% person-detection accuracy in typical deployments, tuned further for your environment on Enterprise plans.": "تصل نماذجنا المدرّبة خصيصاً إلى دقة كشف للأشخاص تتراوح بين 90-95% في عمليات النشر المعتادة، مع ضبط إضافي لبيئتك في باقات المؤسسات.",
    "How is data privacy handled?": "كيف تتم معالجة خصوصية البيانات؟",
