    "MATCH": "میچ جاری",
    "16 GB RAM, an NVIDIA GPU with 8 GB of video memory, 50 GB of free disk": "16 GB RAM، 8 GB ویڈیو میموری والا NVIDIA GPU، 50 GB خالی ڈسک",
    "32 GB RAM, an NVIDIA GPU with 16 GB of video memory, an NVMe SSD": "32 GB RAM، 16 GB ویڈیو میموری والا NVIDIA GPU، ایک NVMe SSD",
    "A Python REST API": "ایک Python REST API",
    "A bird's eye view drawing every player's path as the match plays.": "بالائی منظر جو میچ چلتے ہوئے ہر کھلاڑی کا راستہ بناتا رہتا ہے۔",
    "A broader customer base is served from one system.": "ایک ہی سسٹم سے وسیع تر گاہکوں کو خدمات ملتی ہیں۔",
    "A detector finds the players in every frame and a tracker keeps each identity steady. The four players are locked in as P1 to P4 by court side, and reflections in the glass walls are filtered out.": "ایک ڈیٹیکٹر ہر فریم میں کھلاڑیوں کو پہچانتا ہے اور ٹریکر ہر شناخت کو مستقل رکھتا ہے۔ چاروں کھلاڑی کورٹ کی سمت کے مطابق P1 سے P4 کے طور پر مقرر ہو جاتے ہیں، اور شیشے کی دیواروں میں پڑنے والے عکس چھان کر الگ کر دیے جاتے ہیں۔",
    "A language model running locally writes the answer from those documents and the recent conversation, then lists the sources it used with a confidence score.": "مقامی طور پر چلنے والا لینگویج ماڈل انہی دستاویزات اور حالیہ گفتگو کی بنیاد پر جواب لکھتا ہے، پھر جو ذرائع استعمال کیے وہ اعتماد کے اسکور کے ساتھ درج کرتا ہے۔",
    "A local embedding model, 768 dimensions": "مقامی ایمبیڈنگ ماڈل، 768 ڈائمینشنز",
    "A recorded match video from one fixed camera behind the court, and a one-off calibration where you mark the four court corners. PadelIQ works on recorded video rather than a live club camera stream.": "کورٹ کے پیچھے نصب ایک کیمرے سے ریکارڈ کی گئی میچ ویڈیو، اور ایک بار کی کیلیبریشن جس میں آپ کورٹ کے چاروں کونے نشان زد کرتے ہیں۔ PadelIQ کلب کے لائیو کیمرہ اسٹریم کے بجائے ریکارڈ شدہ ویڈیو پر کام کرتا ہے۔",
    "A server or workstation with an NVIDIA GPU, 8 GB of video memory minimum and 16 GB recommended, and at least 16 GB of RAM. DevelMo can advise on sizing for your team.": "NVIDIA GPU والا سرور یا ورک اسٹیشن، کم از کم 8 GB ویڈیو میموری اور 16 GB تجویز کردہ، اور کم از کم 16 GB RAM۔ DevelMo آپ کی ٹیم کے لیے مناسب گنجائش پر مشورہ دے سکتا ہے۔",
    "A standard match video from one fixed camera behind the court.": "کورٹ کے پیچھے نصب ایک کیمرے سے بنی عام میچ ویڈیو۔",
    "A user types a question in the chat window.": "صارف چیٹ ونڈو میں سوال لکھتا ہے۔",
    "AI coach panel": "AI کوچ پینل",
    "AI coach that turns the numbers into three short, practical tips every few seconds.": "AI کوچ جو ہر چند سیکنڈ بعد اعداد کو تین مختصر، کام آنے والے مشوروں میں بدل دیتا ہے۔",
    "AI service": "AI سروس",
    "AI voice call": "AI وائس کال",
    "Access": "رسائی",
    "Active time": "متحرک وقت",
    "Adapts to what the caller actually says instead of following a rigid script.": "کسی جامد اسکرپٹ پر چلنے کی بجائے کال کرنے والے کی اصل بات کے مطابق ڈھل جاتا ہے۔",
    "Admin console to upload, browse and search the knowledge base.": "نالج بیس اپلوڈ کرنے، دیکھنے اور اس میں تلاش کرنے کے لیے ایڈمن کنسول۔",
    "Admins add documents in the admin console or paste text directly. PDF, Word, Excel, CSV, PowerPoint and plain text are supported.": "ایڈمن اپنے کنسول میں دستاویزات شامل کرتے ہیں یا متن براہِ راست پیسٹ کرتے ہیں۔ PDF، Word، Excel، CSV، PowerPoint اور سادہ متن، سب کی سہولت موجود ہے۔",
    "Annotated match video": "نشان زد میچ ویڈیو",
    "Answer": "جواب",
    "Answers grounded in your own documents, with the source documents listed on every reply.": "جواب آپ ہی کی دستاویزات پر مبنی، اور ہر جواب کے ساتھ ماخذ دستاویزات درج۔",
    "Answers routine questions using data from connected systems.": "جُڑے ہوئے سسٹمز کے ڈیٹا سے روزمرہ سوالوں کے جواب دیتا ہے۔",
    "App database": "ایپ ڈیٹابیس",
    "Appointment management": "اپائنٹمنٹ کا انتظام",
    "Appointment scheduling": "اپائنٹمنٹ کی شیڈولنگ",
    "Arrives in your CRM": "آپ کے CRM میں پہنچ جاتا ہے",
    "Automation platforms": "آٹومیشن پلیٹ فارمز",
    "Average movement speed across the match": "پورے میچ میں حرکت کی اوسط رفتار",
    "Average speed": "اوسط رفتار",
    "Bird's eye mini map that draws every player's movement path as the match plays.": "بالائی منظر کا منی میپ جو میچ چلتے ہوئے ہر کھلاڑی کی حرکت کا راستہ بناتا رہتا ہے۔",
    "Book a demo and we will run DevelMoGPT against a sample of your files.": "ڈیمو بک کریں اور ہم آپ کی فائلوں کے ایک نمونے پر DevelMoGPT چلا کر دکھائیں گے۔",
    "Book a discovery call and we will map one call flow end to end, from the first hello to the CRM update.": "ایک تعارفی کال بک کریں اور ہم پہلے سلام سے CRM کی اپڈیٹ تک ایک پورا کال فلو بنا کر دکھائیں گے۔",
    "Book a viewing, but not cancel a contract": "وزٹ بک کر سکتا ہے، مگر معاہدہ منسوخ نہیں",
