    "Calibrate once": "ایک بار کیلیبریٹ کرنا",
    "Call outcomes are typed into the CRM by hand, late or not at all.": "کال کے نتائج ہاتھ سے CRM میں لکھے جاتے ہیں، دیر سے یا بالکل نہیں۔",
    "Calls new prospects, discovers needs, qualifies them and passes details to sales.": "نئے ممکنہ گاہکوں کو کال کرتا ہے، ان کی ضروریات جانتا ہے، انہیں جانچتا ہے اور تفصیلات سیلز کو دیتا ہے۔",
    "Calls outside working hours or during peaks go unanswered, and leads go cold.": "کام کے اوقات سے باہر یا رش کے وقت آنے والی کالیں بے جواب رہ جاتی ہیں، اور ممکنہ گاہک ہاتھ سے نکل جاتے ہیں۔",
    "Can we try it?": "کیا ہم اسے آزما سکتے ہیں؟",
    "Captures buyer and seller requirements, qualifies them and routes to agents.": "خریدار اور بیچنے والے کی ضروریات نوٹ کرتا ہے، انہیں جانچتا ہے اور ایجنٹس تک پہنچاتا ہے۔",
    "Chat app": "چیٹ ایپ",
    "Check availability and run booking workflows.": "دستیابی دیکھتا ہے اور بکنگ کے ورک فلو چلاتا ہے۔",
