    "Coach": "کوچنگ",
    "Collects post service feedback and flags calls that need attention.": "سروس کے بعد رائے لیتا ہے اور ان کالوں کو نشان زد کرتا ہے جن پر توجہ درکار ہے۔",
    "Connect": "جوڑنا",
    "Connect calls to operations": "کالوں کو کاروباری عمل سے جوڑیں",
    "Context aware": "سیاق و سباق سمجھنے والا",
    "Conversations become CRM updates, API actions, appointments and workflows.": "گفتگو CRM کی اپڈیٹس، API کے عمل، اپائنٹمنٹس اور ورک فلو میں بدل جاتی ہے۔",
    "Converse": "گفتگو کرنا",
    "Court coverage": "کورٹ کا احاطہ",
    "Coverage is capped by headcount and shift hours.": "دستیابی عملے کی تعداد اور شفٹ کے اوقات سے محدود رہتی ہے۔",
    "Create and update leads, contacts, statuses, notes and call outcomes.": "لیڈز، رابطے، اسٹیٹس، نوٹس اور کال کے نتائج بناتا اور اپڈیٹ کرتا ہے۔",
    "Customer feedback": "گاہک کی رائے",
