    "teams": "ٹیمیں",
    "A new lead gets a call within minutes, and sales only hears about the ones worth their time.": "نئے ممکنہ گاہک کو چند منٹوں میں کال آ جاتی ہے، اور سیلز ٹیم کو صرف اُن کے بارے میں معلوم ہوتا ہے جو اُن کے وقت کے قابل ہوں۔",
    "A padel scoreboard tells you who won. It says nothing about who ran further, who held a steady pace, and who covered the court. PadelIQ measures all of it from the video you already record, and an AI coach reads those numbers every few seconds to give short, practical tips.": "پیڈل کا اسکور بورڈ آپ کو بتاتا ہے کہ کون جیتا۔ یہ کچھ نہیں بتاتا کہ کون زیادہ دوڑا، کس نے رفتار مستقل رکھی، اور کس نے کورٹ کو سنبھالا۔ PadelIQ یہ سب اُسی ویڈیو سے ناپتا ہے جو آپ پہلے ہی ریکارڈ کرتے ہیں، اور ایک AI کوچ ہر چند سیکنڈ میں اِن اعداد کو پڑھ کر مختصر اور کارآمد مشورے دیتا ہے۔",
    "A voice layer, and everything around it": "آواز کی ایک تہہ، اور اُس کے گرد سب کچھ",
    "AI that reads the game": "AI جو کھیل کو پڑھتا ہے",
    "Act": "عمل کرنا",
    "Agent": "ایجنٹ",
    "An AI voice agent that talks to your customers in their language and gets real work done in your CRM, calendar and systems. Connect the AI to your systems, not the other way around.": "ایک AI وائس ایجنٹ جو آپ کے گاہکوں سے اُن کی زبان میں بات کرتا ہے اور آپ کے CRM، کیلنڈر اور نظاموں میں حقیقی کام کر دیتا ہے۔ AI کو اپنے نظاموں سے جوڑیں، اُلٹا نہیں۔",
    "An appointment, a CRM update, an API action, a notification, or a handoff to the right person.": "ایک اپائنٹمنٹ، CRM میں ایک اپ ڈیٹ، ایک API ایکشن، ایک اطلاع، یا درست فرد کے حوالے کرنا۔",
    "Ball tracking and ball trails are being built and are not part of the product yet.": "بال ٹریکنگ اور بال ٹریلز پر کام جاری ہے اور یہ ابھی پروڈکٹ کا حصہ نہیں ہیں۔",
    "Because each deployment is configured around your languages, business logic and integrations, one voice system can serve a local market or customers across several regions with a consistent experience. In our core markets that usually means Arabic and English on the same line.": "چونکہ ہر تنصیب آپ کی زبانوں، کاروباری منطق اور انٹیگریشنز کے مطابق ترتیب دی جاتی ہے، اِس لیے ایک ہی وائس سسٹم کسی مقامی مارکیٹ یا کئی خطوں کے گاہکوں کو ایک جیسا تجربہ دے سکتا ہے۔ ہماری بنیادی مارکیٹوں میں اِس کا مطلب عام طور پر ایک ہی لائن پر عربی اور انگریزی ہوتا ہے۔",
    "Benefit": "فائدہ",
    "Book a demo": "ڈیمو بُک کریں",
    "Book a discovery call": "تعارفی کال بُک کریں",
    "Booked": "بُک ہو گیا",
    "Business value": "کاروباری قدر",
    "Businesses depend on calls for sales, support, appointments, recruitment and follow ups, and every extra call needs another person. What they need is a way to scale conversations while keeping every call connected to real business processes.": "کاروبار سیلز، سپورٹ، اپائنٹمنٹس، بھرتی اور فالو اَپ کے لیے کالوں پر انحصار کرتے ہیں، اور ہر اضافی کال کے لیے ایک اور فرد درکار ہوتا ہے۔ اُنہیں ایسا طریقہ چاہیے جس سے گفتگو کا دائرہ بڑھے اور ہر کال حقیقی کاروباری عمل سے جُڑی رہے۔",
