    "Configured, not templated": "ترتیب دیا گیا، ٹیمپلیٹ سے نہیں",
    "Contracts, policies, handbooks and reports pile up faster than anyone can read them, and the assistants that could answer questions about them want the files uploaded somewhere else. For teams with data residency rules, or anything commercially sensitive, that is the end of the conversation.": "معاہدے، پالیسیاں، ہینڈ بُکس اور رپورٹیں اُس سے زیادہ تیزی سے جمع ہوتی ہیں جتنا کوئی اُنہیں پڑھ سکے، اور جو اسسٹنٹ اِن کے بارے میں سوالوں کے جواب دے سکتے ہیں وہ فائلیں کہیں اور اپ لوڈ کرانا چاہتے ہیں۔ جن ٹیموں پر ڈیٹا کی جگہ سے متعلق قواعد لاگو ہوں، یا جن کے پاس تجارتی لحاظ سے حساس کوئی بھی چیز ہو، اُن کے لیے بات وہیں ختم ہو جاتی ہے۔",
    "Customer": "گاہک",
    "DevelMoGPT is a private AI chat assistant that runs entirely on your own hardware. Upload your company documents and your team can ask questions in plain language and get answers drawn from those documents, with the source files listed on every reply.": "DevelMoGPT ایک نجی AI چیٹ اسسٹنٹ ہے جو مکمل طور پر آپ کے اپنے ہارڈ ویئر پر چلتا ہے۔ اپنی کمپنی کی دستاویزات اپ لوڈ کریں اور آپ کی ٹیم سادہ زبان میں سوال پوچھ کر اُن دستاویزات سے نکالے گئے جواب حاصل کر سکتی ہے، اور ہر جواب کے ساتھ ماخذ فائلوں کی فہرست ہوتی ہے۔",
    "DevelMoGPT is a working prototype. We are taking it into pilots now, so the honest next step is a demo on a sample of your own documents.": "DevelMoGPT ایک کام کرتا ہوا پروٹوٹائپ ہے۔ ہم اِسے اب پائلٹ مراحل میں لے جا رہے ہیں، اِس لیے ایمانداری سے اگلا قدم آپ کی اپنی دستاویزات کے ایک نمونے پر ڈیمو ہے۔",
    "Do you have anything free on Thursday morning?": "کیا جمعرات کی صبح آپ کے پاس کوئی وقت خالی ہے؟",
    "ElevenLabs handles voice generation and real time voice interaction. DevelMo combines that voice layer with conversational intelligence, integrations, business logic and automation to deliver a complete voice based business system.": "ElevenLabs آواز کی تخلیق اور حقیقی وقت میں آواز کے تعامل کو سنبھالتا ہے۔ DevelMo اُس آواز کی تہہ کو گفتگو کی ذہانت، انٹیگریشنز، کاروباری منطق اور آٹومیشن کے ساتھ ملا کر ایک مکمل آواز پر مبنی کاروباری نظام فراہم کرتا ہے۔",
    "ElevenLabs voice": "ElevenLabs کی آواز",
