    "One voice platform, many jobs": "ایک وائس پلیٹ فارم، بہت سے کام",
    "PadelIQ began as a structured community league, built so players could form teams, record real results, and compete through transparent rankings and seasonal tournaments including the RPF Grand Slam.": "PadelIQ کا آغاز ایک منظم کمیونٹی لیگ کے طور پر ہوا، جو اِس لیے بنائی گئی کہ کھلاڑی ٹیمیں بنا سکیں، حقیقی نتائج درج کر سکیں، اور شفاف رینکنگ اور موسمی ٹورنامنٹس بشمول RPF گرینڈ سلیم کے ذریعے مقابلہ کر سکیں۔",
    "PadelIQ turns ordinary match video into performance data for every player. It finds all four players, follows each one through the match, maps every step onto the real court, and reports distance, speed, court coverage and work rate in real units.": "PadelIQ عام میچ ویڈیو کو ہر کھلاڑی کے لیے کارکردگی کے ڈیٹا میں بدل دیتا ہے۔ یہ چاروں کھلاڑیوں کو پہچانتا ہے، پورے میچ میں ہر ایک کا تعاقب کرتا ہے، ہر قدم کو حقیقی کورٹ پر نقشہ بند کرتا ہے، اور فاصلہ، رفتار، کورٹ کی کوریج اور کام کی شرح حقیقی اکائیوں میں بتاتا ہے۔",
    "Pain point": "مسئلہ",
