    "Scheduling, follow up, handoff": "شیڈولنگ، فالو اَپ، حوالگی",
    "Six things it does on every call": "ہر کال پر یہ چھ کام کرتا ہے",
    "System": "نظام",
    "The Riyadh Padel Federation runs on it": "ریاض پیڈل فیڈریشن اِسی پر چلتی ہے",
    "The agent is designed around your existing data infrastructure and access requirements, so you set the boundaries. That is what lets an organisation add voice automation on top of its own stack instead of moving a whole workflow into a separate platform.": "ایجنٹ آپ کے موجودہ ڈیٹا انفراسٹرکچر اور رسائی کی ضروریات کے گرد بنایا جاتا ہے، اِس لیے حدود آپ طے کرتے ہیں۔ یہی بات کسی ادارے کو یہ سہولت دیتی ہے کہ وہ پورا ورک فلو کسی الگ پلیٹ فارم پر منتقل کرنے کے بجائے اپنے ہی اسٹیک کے اوپر وائس آٹومیشن شامل کر لے۔",
    "The agent understands what the caller wants, asks the right questions, pulls information from connected systems and acts on it. It is a conversational front end to your infrastructure rather than an isolated chatbot.": "ایجنٹ سمجھتا ہے کہ کال کرنے والا کیا چاہتا ہے، درست سوال پوچھتا ہے، جُڑے ہوئے نظاموں سے معلومات لاتا ہے اور اُن پر عمل کرتا ہے۔ یہ کسی الگ تھلگ چیٹ بوٹ کے بجائے آپ کے انفراسٹرکچر کا گفتگو پر مبنی فرنٹ اینڈ ہے۔",
    "The analytics": "تجزیات",
    "The answer is in a folder nobody can search": "جواب ایک ایسے فولڈر میں ہے جسے کوئی تلاش نہیں کر سکتا",
    "The league": "لیگ",
    "The same architecture adapts to support, recruitment, appointment management and other workflows.": "یہی ساخت سپورٹ، بھرتی، اپائنٹمنٹ کے انتظام اور دیگر ورک فلوز کے مطابق ڈھل جاتی ہے۔",
    "There is a 10:30 slot. Shall I hold it for you?": "10:30 کا وقت خالی ہے۔ کیا میں آپ کے لیے رکھ لوں؟",
    "There is no one size fits all conversation. Every business has different customers, data, qualification criteria, systems and processes, so each agent is built around your conversation flow, business rules, data sources, CRM, APIs, scheduling and escalation rules.": "کوئی ایک گفتگو سب پر پوری نہیں اُترتی۔ ہر کاروبار کے گاہک، ڈیٹا، جانچ کے معیار، نظام اور طریقے مختلف ہوتے ہیں، اِس لیے ہر ایجنٹ آپ کے گفتگو کے بہاؤ، کاروباری قواعد، ڈیٹا کے ذرائع، CRM، APIs، شیڈولنگ اور معاملہ آگے بڑھانے کے قواعد کے گرد بنایا جاتا ہے۔",
