    "How is data privacy handled?": "ڈیٹا کی پرائیویسی کیسے سنبھالی جاتی ہے؟",
    "CrowdIQ is privacy-aware by design and can run in the cloud, on-premise or at the edge so footage and data stay where you need them.": "CrowdIQ بنیادی ڈیزائن کے اعتبار سے پرائیویسی سے آگاہ ہے اور کلاؤڈ، آن پریمائز یا ایج پر چل سکتا ہے تاکہ فوٹیج اور ڈیٹا وہیں رہیں جہاں آپ چاہتے ہیں۔",
    "Can it run on-premise?": "کیا یہ آن پریمائز چل سکتا ہے؟",
