    "Modern products, platforms and experiences that move your business online and ahead.": "Des produits, plateformes et expériences modernes qui propulsent votre entreprise en ligne et vers l'avant.",
    "Turn data into decisions, predictions and intelligent automation.": "Transformez vos données en décisions, prévisions et automatisation intelligente.",
    "Systems that see, understand and act on the physical and visual world.": "Des systèmes qui voient, comprennent et agissent sur le monde physique et visuel.",
    "Secure your stack and adopt what comes next, with a clear plan.": "Sécurisez votre stack et adoptez les technologies de demain, avec une feuille de route claire.",
    "Build, scale and ship cloud and AI infrastructure, end to end.": "Concevez, faites évoluer et déployez votre infrastructure cloud et IA, de bout en bout.",
    "Add specialist engineers and teams on demand.": "Renforcez vos effectifs avec des ingénieurs et des équipes spécialisés, à la demande.",
    "Custom that fits": "Du sur-mesure qui s'adapte",
    "Solutions shaped around your data, goals and operations, never forced into a template.": "Des solutions pensées autour de vos données, de vos objectifs et de vos opérations, jamais coulées dans un moule.",
    "Product mindset": "Une approche produit",
    "We build for production, with quality, measurement and maintainability from day one.": "Nous concevons pour la production, avec qualité, mesure et maintenabilité dès le premier jour.",
    "Flexible teams": "Des équipes flexibles",
    "Scale specialist talent up or down on demand without growing your headcount.": "Ajustez vos talents spécialisés à la hausse ou à la baisse, à la demande, sans alourdir vos effectifs.",
    "Enterprise delivery": "Une livraison à l'échelle de l'entreprise",
    "Scalable, secure delivery trusted across 23+ countries.": "Une livraison évolutive et sécurisée, plébiscitée dans plus de 23 pays.",
    "Every DevelMo product here runs in production today, not as a demo. Adopt it as it is, or have it tailored to your environment.": "Chaque produit DevelMo présenté ici tourne aujourd'hui en production, et non en démonstration. Adoptez-le tel quel, ou faites-le adapter à votre environnement.",
    "One partner across the full stack of AI, product and infrastructure, with flexible teams that scale up or down with you.": "Un partenaire unique sur toute la chaîne de l'IA, du produit et de l'infrastructure, avec des équipes flexibles qui évoluent à votre rythme.",
    "Domain-aware delivery across the sectors where AI moves the needle on cost, risk and growth.": "Une expertise métier dans les secteurs où l'IA fait réellement la différence en matière de coûts, de risques et de croissance.",
    "Technology should fit your business, not the other way around. That belief shapes how we scope, build and hand over every project.": "La technologie doit s'adapter à votre entreprise, et non l'inverse. Cette conviction guide notre façon de cadrer, de construire et de livrer chaque projet.",
