    "Build AI that fits, with us": "Construisez avec nous une IA qui vous ressemble",
    "Scaling businesses through AI that fits. One partner across the full stack of AI, product and infrastructure.": "Faire grandir les entreprises grâce à une IA sur-mesure. Un partenaire unique sur toute la chaîne de l'IA, du produit et de l'infrastructure.",
    "DevelMo builds and ships its own AI products, so you can adopt proven intelligence fast or have it tailored to your environment.": "DevelMo conçoit et déploie ses propres produits d'IA : adoptez rapidement une intelligence éprouvée ou faites-la adapter à votre environnement.",
    "We are a distributed team shipping custom AI, software and automation for clients across 23+ countries.": "Nous sommes une équipe distribuée qui livre de l'IA, des logiciels et de l'automatisation sur-mesure à des clients dans plus de 23 pays.",
    "Practical notes on AI, computer vision, cloud and building software that actually ships.": "Des retours concrets sur l'IA, la vision par ordinateur, le cloud et la création de logiciels qui voient vraiment le jour.",
    "Guides, insights and practical resources from the DevelMo team.": "Guides, analyses et ressources pratiques signés par l'équipe DevelMo.",
    "A look at the kinds of outcomes we deliver. Detailed, named case studies are added here as clients approve them.": "Un aperçu des résultats que nous obtenons. Des études de cas détaillées et nominatives sont ajoutées ici au fur et à mesure des accords de nos clients.",
    "Tell us what you are building or the problem you want to solve. We will map the highest-impact opportunity and reply within one business day.": "Parlez-nous de votre projet ou du problème que vous souhaitez résoudre. Nous identifierons l'opportunité la plus prometteuse et vous répondrons sous un jour ouvré.",
