    "FAQ": "FAQ",
    "Common questions": "Questions fréquentes",
    "What cameras does CrowdIQ work with?": "Avec quelles caméras CrowdIQ fonctionne-t-il ?",
    "Any camera that exposes an RTSP, ONVIF or HTTP stream, plus local cameras and webcams. You do not need to replace existing hardware.": "Toute caméra exposant un flux RTSP, ONVIF ou HTTP, ainsi que les caméras locales et les webcams. Vous n'avez pas besoin de remplacer votre matériel existant.",
    "How accurate is detection?": "Quelle est la précision de la détection ?",
    "Our custom-trained models reach 90-95% person-detection accuracy in typical deployments, tuned further for your environment on Enterprise plans.": "Nos modèles entraînés sur-mesure atteignent une précision de détection des personnes de 90-95% dans des déploiements classiques, et sont affinés pour votre environnement avec les forfaits Enterprise.",
    "How is data privacy handled?": "Comment la confidentialité des données est-elle gérée ?",
    "CrowdIQ is privacy-aware by design and can run in the cloud, on-premise or at the edge so footage and data stay where you need them.": "CrowdIQ est conçu dans le respect de la confidentialité et peut fonctionner dans le cloud, sur site ou en périphérie, afin que vos images et vos données restent là où vous le souhaitez.",
    "Can it run on-premise?": "Peut-il fonctionner sur site ?",
    "Yes. Enterprise deployments support on-premise and edge so video never has to leave your network.": "Oui. Les déploiements Enterprise prennent en charge le sur site et la périphérie, de sorte que la vidéo n'a jamais à quitter votre réseau.",
    "How long does setup take?": "Combien de temps prend l'installation ?",
    "Most teams connect a first camera and see live insight the same day.": "La plupart des équipes connectent une première caméra et obtiennent des analyses en direct le jour même.",
    "See CrowdIQ on your cameras": "Découvrez CrowdIQ sur vos caméras",
    "Request a demo and we will connect CrowdIQ to a sample feed so you can see the insight it produces.": "Demandez une démo et nous connecterons CrowdIQ à un flux d'exemple afin que vous puissiez constater les analyses qu'il produit.",
