    "Modern products, platforms and experiences that move your business online and ahead.": "Productos, plataformas y experiencias modernas que llevan tu negocio al mundo digital y lo hacen avanzar.",
    "Turn data into decisions, predictions and intelligent automation.": "Convierte los datos en decisiones, predicciones y automatización inteligente.",
    "Systems that see, understand and act on the physical and visual world.": "Sistemas que ven, comprenden y actúan sobre el mundo físico y visual.",
    "Secure your stack and adopt what comes next, with a clear plan.": "Protege tu stack y adopta lo que viene, con un plan claro.",
    "Build, scale and ship cloud and AI infrastructure, end to end.": "Crea, escala y despliega infraestructura cloud y de IA, de principio a fin.",
    "Add specialist engineers and teams on demand.": "Suma ingenieros y equipos especializados bajo demanda.",
    "Custom that fits": "Soluciones a tu medida",
    "Solutions shaped around your data, goals and operations, never forced into a template.": "Soluciones diseñadas en torno a tus datos, objetivos y operaciones, nunca forzadas a una plantilla.",
    "Product mindset": "Mentalidad de producto",
    "We build for production, with quality, measurement and maintainability from day one.": "Construimos para producción, con calidad, medición y mantenibilidad desde el primer día.",
    "Flexible teams": "Equipos flexibles",
    "Scale specialist talent up or down on demand without growing your headcount.": "Escala el talento especializado hacia arriba o hacia abajo bajo demanda, sin ampliar tu plantilla.",
    "Enterprise delivery": "Entrega de nivel empresarial",
    "Scalable, secure delivery trusted across 23+ countries.": "Entrega escalable y segura, con la confianza de más de 23 países.",
    "Every DevelMo product here runs in production today, not as a demo. Adopt it as it is, or have it tailored to your environment.": "Cada producto de DevelMo que ve aquí funciona hoy en producción, no en una demostración. Adóptelo tal cual, o pida que lo adaptemos a su entorno.",
    "One partner across the full stack of AI, product and infrastructure, with flexible teams that scale up or down with you.": "Un solo socio que abarca todo el stack de IA, producto e infraestructura, con equipos flexibles que escalan contigo.",
    "Domain-aware delivery across the sectors where AI moves the needle on cost, risk and growth.": "Entrega con conocimiento del sector en las industrias donde la IA marca la diferencia en costo, riesgo y crecimiento.",
    "Technology should fit your business, not the other way around. That belief shapes how we scope, build and hand over every project.": "La tecnología debe adaptarse a tu negocio, no al revés. Esa convicción define cómo planificamos, construimos y entregamos cada proyecto.",
