    "Scaling businesses through AI that fits. One partner across the full stack of AI, product and infrastructure.": "Hacemos crecer negocios con IA a la medida. Un solo socio en todo el stack de IA, producto e infraestructura.",
    "DevelMo builds and ships its own AI products, so you can adopt proven intelligence fast or have it tailored to your environment.": "DevelMo desarrolla y lanza sus propios productos de IA, para que adoptes inteligencia probada rápidamente o la adaptes a tu entorno.",
    "We are a distributed team shipping custom AI, software and automation for clients across 23+ countries.": "Somos un equipo distribuido que entrega IA, software y automatización a la medida para clientes en más de 23 países.",
    "Practical notes on AI, computer vision, cloud and building software that actually ships.": "Notas prácticas sobre IA, visión por computadora, cloud y cómo construir software que realmente se lanza.",
    "Guides, insights and practical resources from the DevelMo team.": "Guías, análisis y recursos prácticos del equipo de DevelMo.",
    "A look at the kinds of outcomes we deliver. Detailed, named case studies are added here as clients approve them.": "Un vistazo a los resultados que logramos. Aquí agregamos casos de éxito detallados y con nombre a medida que los clientes los aprueban.",
    "Tell us what you are building or the problem you want to solve. We will map the highest-impact opportunity and reply within one business day.": "Cuéntanos qué estás construyendo o el problema que quieres resolver. Identificaremos la oportunidad de mayor impacto y te responderemos en un día hábil.",
