    "Common questions": "Preguntas comunes",
    "What cameras does CrowdIQ work with?": "¿Con qué cámaras funciona CrowdIQ?",
    "Any camera that exposes an RTSP, ONVIF or HTTP stream, plus local cameras and webcams. You do not need to replace existing hardware.": "Cualquier cámara que exponga una transmisión RTSP, ONVIF o HTTP, además de cámaras locales y webcams. No necesitas reemplazar el hardware existente.",
    "How accurate is detection?": "¿Qué tan precisa es la detección?",
    "Our custom-trained models reach 90-95% person-detection accuracy in typical deployments, tuned further for your environment on Enterprise plans.": "Nuestros modelos entrenados a la medida alcanzan una precisión de detección de personas del 90-95% en despliegues típicos, ajustada aún más a tu entorno en los planes Enterprise.",
    "How is data privacy handled?": "¿Cómo se gestiona la privacidad de los datos?",
    "CrowdIQ is privacy-aware by design and can run in the cloud, on-premise or at the edge so footage and data stay where you need them.": "CrowdIQ prioriza la privacidad por diseño y puede ejecutarse en la nube, on-premise o en el edge para que las imágenes y los datos permanezcan donde los necesitas.",
    "Can it run on-premise?": "¿Puede ejecutarse on-premise?",
    "Yes. Enterprise deployments support on-premise and edge so video never has to leave your network.": "Sí. Los despliegues Enterprise admiten on-premise y edge para que el video nunca tenga que salir de tu red.",
    "How long does setup take?": "¿Cuánto tarda la configuración?",
    "Most teams connect a first camera and see live insight the same day.": "La mayoría de los equipos conectan su primera cámara y ven información en vivo el mismo día.",
    "See CrowdIQ on your cameras": "Mira CrowdIQ en tus cámaras",
    "Request a demo and we will connect CrowdIQ to a sample feed so you can see the insight it produces.": "Solicita una demo y conectaremos CrowdIQ a una señal de muestra para que veas la información que produce.",
